u: 0, pi/2, 40
v: -1, 1, 40
//MESH_END

// Calabi-Yau: 2D section of the Fermat quintic, degree n chosen by the slider.
//   z1^n + z2^n = 1,  with z1,z2 complex
// For each pair of n-th roots of unity (k1,k2) there is a patch:
//   z1 = e^(2 pi i k1/n) * (cos w)^(2/n)
//   z2 = e^(2 pi i k2/n) * (sin w)^(2/n)     with w = u + i v
// With n = 5 it is the canonical figure of the string theory illustrations.
//
// INTEGER DEGREE: the grids are STATIC (read at Run), so we declare their
// maximum -- 25 = 5x5 -- and discard the extra ones in the cutout. The indices
// are NOT in a fixed base 5: they are computed on the live grid (k1 = mesh % n,
// k2 = mesh / n), so the surviving patches are the first n*n and the mesh
// counter never offers numbers that point to discarded patches.
//
// 3D VERSION: the fourth dimension is projected HERE, mixed into
// z by the angle B (0.785 = pi/4 is the canonical framing). The w component
// of the vec4 stays 0, so the figure does not depend on the 4D rotations.

A := int(2,5);          // grado della quintica: slider a scatti interi
MESH_VISIBLE := A*A;    // quante griglie sopravvivono al cutout

float n  = clamp(floor(A + 0.5), 2.0, 5.0);
// COMPACT NUMBERING: the indices are computed on the LIVE grid (n x n),
// not on the fixed base 5. This way the surviving patches are the FIRST n*n in
// mesh order, and the interface counter (which maps number -> mesh as
// value()-1) always points to a patch that is actually visible.
// With the old base 5 the live ones were 0,1,2, 5,6,7, 10... and from the fourth
// number on the selector fell on patches discarded by the cutout: inert sliders.
// The (k1,k2) PAIRS drawn are the same as before: what changes is the index that
// carries them, not the figure.
float k1 = mod(float(mesh), n);
float k2 = floor(float(mesh) / n);
float p  = 2.0 / n;

// w = u + i v;  cos(w) e sin(w) complessi
vec2 cw = vec2( cos(u) * cosh(v), -sin(u) * sinh(v));
vec2 sw = vec2( sin(u) * cosh(v),  cos(u) * sinh(v));

// Complex power in polar form. On the declared domain Re(cos w) and
// Re(sin w) stay POSITIVE: the argument lies in (-pi/2, pi/2), far from the
// atan jump, so there is no branch cut and no seams between patches.
float rc = safePow(length(cw), p);
float tc = p * atan(cw.y, cw.x);
float rs = safePow(length(sw), p);
float ts = p * atan(sw.y, sw.x);

// Radici n-esime dell'unita': e^(2 pi i k/n)
float a1 = 2.0 * pi * k1 / n;
float a2 = 2.0 * pi * k2 / n;

vec2 z1 = rc * vec2(cos(tc + a1), sin(tc + a1));
vec2 z2 = rs * vec2(cos(ts + a2), sin(ts + a2));

// R^4 -> R^3: the two real parts, the imaginary ones mixed by the angle B
return vec4(z1.x,
            z2.x,
            cos(B) * z1.y + sin(B) * z2.y,
            0.0);

//CUTOUT_BEGIN
// Discard the TAIL: with the compact numbering of the body the live patches are
// the first nc*nc, so a comparison on the index is enough. The clamp stays
// replicated identical to the body (n), or the live patches do not match.
float nc = clamp(floor(A + 0.5), 2.0, 5.0);
return float(mesh) > nc * nc - 0.5;
//CUTOUT_END
